  "parent.p2t": "দায়িত্বশীল AI ব্যবহার", "parent.p2d": "AI গুরু শেখাকে সাহায্য করার জন্য তৈরি, প্রতিস্থাপন করার জন্য নয়।",
  "parent.p3t": "কন্টেন্ট মডারেশন", "parent.p3d": "স্কিল ব্যাটেল ও রিলস সাবমিশন মডারেশনের কথা মাথায় রেখে ডিজাইন করা হয়েছে।",
  "parent.p4t": "প্রাইভেসি সবার আগে", "parent.p4d": "ছাত্র ডেটা ভারতের DPDP আইন অনুযায়ী আমাদের প্রাইভেসি পলিসি মেনে পরিচালিত হয়।",
  "how.eyebrow": "এটি কীভাবে কাজ করে", "how.h2": "চারটি সহজ ধাপে শুরু করুন",
  "how.sub": "কোনো ওয়েটিং লিস্ট নেই। কোনো আমন্ত্রণের দরকার নেই। শুধু অ্যাকাউন্ট তৈরি করুন এবং শুরু করুন।",
  "how.step1t": "আপনার বিনামূল্যের অ্যাকাউন্ট তৈরি করুন", "how.step1d": "আপনার ফোন বা ইমেইল দিয়ে মিনিটেই সাইন আপ করুন।",
  "how.step2t": "আপনার লার্নিং জার্নি বেছে নিন", "how.step2d": "আপনার ক্লাস, বোর্ড ও পছন্দের ভাষা সেট করুন।",
  "how.step3t": "শিখুন, অনুশীলন করুন ও প্রতিযোগিতা করুন", "how.step3d": "AI গুরু ব্যবহার করুন, কুইজ দিন এবং স্কিল ব্যাটেলে যোগ দিন।",
  "how.cta": "বিনামূল্যে শুরু করুন →",

