  "faq.q1": "Gloows365 কি বিনামূল্যে?",
  "faq.a1": "হ্যাঁ — আপনি Gloows365-এ বিনামূল্যে অ্যাকাউন্ট তৈরি করে শেখা শুরু করতে পারেন।",
  "faq.q2": "কোন ক্লাসগুলি সাপোর্টেড?",
  "faq.a2": "Gloows365 বর্তমানে ক্লাস ৬ থেকে ১২ পর্যন্ত ছাত্রছাত্রীদের সাপোর্ট করে।",
  "faq.q3": "কোন বোর্ডগুলি সাপোর্টেড?",
  "faq.a3": "CBSE, ICSE, স্টেট বোর্ড এবং অন্যান্য বোর্ড সাপোর্টেড।",
  "faq.q4": "Gloows365 কি ভারতীয় ভাষা সাপোর্ট করে?",
  "faq.a4": "হ্যাঁ — Gloows365 ১২টি ভারতীয় ভাষায় উপলব্ধ।",
  "faq.q5": "Gloows365 কি অ্যান্ড্রয়েডে উপলব্ধ?",
  "faq.a5": "Gloows365 আজ একটি ওয়েব অভিজ্ঞতা হিসেবে উপলব্ধ — সাইন আপ করুন এবং যেকোনো ব্রাউজার থেকে শেখা শুরু করুন।",
  "faq.q6": "Gloows365 কি অভিভাবকদের জন্য নাকি ছাত্রছাত্রীদের জন্য?",
  "faq.a6": "উভয়ের জন্য। ছাত্রছাত্রীরা শেখা, অনুশীলন ও এগিয়ে যাওয়ার জন্য Gloows365 ব্যবহার করে, আর অভিভাবকরা এটিকে একটি সুসংগঠিত, শিক্ষা-কেন্দ্রিক অভিজ্ঞতা হিসেবে বিশ্বাস করতে পারেন।",
  "faq.q7": "AI গুরু কী?",
  "faq.a7": "AI গুরু হল Gloows365-এর AI-চালিত লার্নিং সঙ্গী, যা ছাত্রছাত্রীদের প্রশ্ন করতে, ধারণা অন্বেষণ করতে এবং লার্নিং সহায়তা পেতে সাহায্য করার জন্য তৈরি।",
  "faq.q8": "বিদ্যা স্টার কী?",
  "faq.a8": "বিদ্যা স্টার হল একটি MCQ-ভিত্তিক নলেজ চ্যালেঞ্জ যা রিভিশনকে একটি আকর্ষণীয় কার্যকলাপে পরিণত করে।",
  "faq.q9": "শিক্ষামূলক রিলস কী?",
  "faq.a9": "শিক্ষামূলক রিলস হল ছোট ভিডিও যা উপযোগী জ্ঞানকে সেকেন্ডে শেখা সহজ করার জন্য তৈরি।",
