  "hero.eyebrow": "Gloows365 லைவ் — இன்றே இலவசமாகத் தொடங்குங்கள்",
  "hero.h1line1": "புத்திசாலித்தனமாகக் கற்றுக்கொள்ளுங்கள். போட்டியிடுங்கள்.", "hero.h1line2": "உருவாக்குங்கள். வெல்லுங்கள்.",
  "hero.sub": "Gloows365 என்பது 6–12ஆம் வகுப்பு மாணவர்களுக்காக வடிவமைக்கப்பட்ட AI-இயங்கும் கற்றல் மற்றும் திறன் தளமாகும். உங்கள் மொழியில் கற்றுக்கொள்ளுங்கள், உங்களை சவால் செய்யுங்கள், உங்கள் திறமையை வெளிப்படுத்துங்கள், இந்தியா முழுவதும் உள்ள மாணவர்களுடன் போட்டியிடுங்கள்.",
  "hero.ctaPrimary": "🚀 லாகின் / சைன் அப் — இலவசம்", "hero.ctaSecondary": "Gloows365-ஐ ஆராயுங்கள்",
