  "vidyaStar.eyebrow": "வித்யா ஸ்டார்", "vidyaStar.h2": "அறிவை சாதனையாக மாற்றுங்கள்.",
  "vidyaStar.sub": "ஒரு தலைப்பைப் படியுங்கள், உங்களை சோதியுங்கள், நீங்கள் எங்கு நிற்கிறீர்கள் என்பதைப் பாருங்கள் — ஒரு படி ஒரு நேரத்தில்.",
  "vs.step1": "ஒரு தலைப்பைக் கற்றுக்கொள்ளுங்கள்", "vs.step1desc": "ஒரு பாடத்தைத் தேர்ந்தெடுத்து உங்கள் வேகத்தில் படியுங்கள்.",
  "vs.step2": "AI-இயங்கும் கேள்விகளுக்கு பதிலளியுங்கள்", "vs.step2desc": "நீங்கள் படித்ததற்கு பொருந்தும் MCQ களுடன் பயிற்சி செய்யுங்கள்.",
  "vs.step3": "உங்கள் அறிவை சோதியுங்கள்", "vs.step3desc": "சவாலை எடுத்து நீங்கள் எவ்வளவு நன்றாக அறிந்திருக்கிறீர்கள் என்பதைப் பாருங்கள்.",
  "vs.step4": "போட்டியிடுங்கள்", "vs.step4desc": "அதே தலைப்பைக் கற்கும் மற்ற மாணவர்களுக்கு எதிராக போட்டியிடுங்கள்.",
  "vs.step5": "அங்கீகாரம் & வெகுமதிகள் பெறுங்கள்", "vs.step5desc": "சிறந்த செயல்திறன் செயலிக்குள் அங்கீகரிக்கப்படுகிறது.",
  "vidyaStar.cta": "வித்யா ஸ்டாரை ஆராயுங்கள் →",

  "lang.eyebrow": "இந்தியாவுக்காக வடிவமைக்கப்பட்டது", "lang.h2": "இந்தியா பல மொழிகளில் கற்கிறது.",
  "lang.sub": "இந்தியாவின் பல்வேறு மொழிகள் மற்றும் மாணவர் சமூகங்களில் கற்றலை அணுகக்கூடியதாக்க Gloows365 வடிவமைக்கப்பட்டுள்ளது.",

  "cb.eyebrow": "மாணவரை மையமாகக் கொண்டு உருவாக்கப்பட்டது", "cb.h2": "ஒவ்வொரு வகுப்பும். ஒவ்வொரு முக்கிய வாரியமும்.",
  "cb.classesLabel": "வகுப்புகள்", "cb.boardsLabel": "வாரியங்கள்", "cb.stateBoard": "மாநில வாரியம்", "cb.other": "மற்றவை",

  "parent.eyebrow": "பெற்றோர்களுக்கு", "parent.h2": "மாணவர்களுக்காக உருவாக்கப்பட்டது. பெற்றோரின் நம்பிக்கை.",
  "parent.sub": "மாணவர் பாதுகாப்பு மற்றும் பொறுப்புள்ள பங்கேற்பை மனதில் கொண்டு Gloows365 வடிவமைக்கப்பட்டுள்ளது.",
  "parent.p1t": "வயதுக்கு ஏற்ற கற்றல்", "parent.p1d": "உள்ளடக்கமும் அம்சங்களும் குறிப்பாக வகுப்பு 6–12 க்காக உருவாக்கப்பட்டவை.",
  "parent.p2t": "பொறுப்பான AI பயன்பாடு", "parent.p2d": "AI குரு கற்றலுக்கு உதவும் வகையில் வடிவமைக்கப்பட்டுள்ளது, அதற்குப் பதிலாக அல்ல.",
  "parent.p3t": "உள்ளடக்க மேலாண்மை", "parent.p3d": "ஸ்கில் பேட்டில் மற்றும் ரீல்ஸ் சமர்ப்பிப்புகள் மேலாண்மையை மனதில் கொண்டு வடிவமைக்கப்பட்டுள்ளன.",
  "parent.p4t": "தனியுரிமை முதலில்", "parent.p4d": "மாணவர் தரவு இந்தியாவின் DPDP சட்டத்தின் கீழ் எங்கள் தனியுரிமைக் கொள்கையின்படி கையாளப்படுகிறது.",
  "how.eyebrow": "இது எப்படி வேலை செய்கிறது", "how.h2": "நான்கு எளிய படிகளில் தொடங்குங்கள்",
  "how.sub": "காத்திருப்பு பட்டியல் இல்லை. அழைப்பு தேவையில்லை. உங்கள் கணக்கை உருவாக்கி தொடங்குங்கள்.",
  "how.step1t": "உங்கள் இலவச கணக்கை உருவாக்குங்கள்", "how.step1d": "உங்கள் தொலைபேசி அல்லது மின்னஞ்சலுடன் நிமிடங்களில் பதிவு செய்யுங்கள்.",
  "how.step2t": "உங்கள் கற்றல் பயணத்தைத் தேர்ந்தெடுங்கள்", "how.step2d": "உங்கள் வகுப்பு, வாரியம் மற்றும் விருப்ப மொழியை அமைக்கவும்.",
  "how.step3t": "கற்றுக்கொள்ளுங்கள், பயிற்சி செய்யுங்கள் & போட்டியிடுங்கள்", "how.step3d": "AI குருவைப் பயன்படுத்துங்கள், வினாடி வினாக்களை எடுங்கள், ஸ்கில் பேட்டிலில் சேருங்கள்.",
  "how.cta": "இலவசமாகத் தொடங்குங்கள் →",

  "final.h2": "அற்புதமான ஒன்றைக் கற்றுக்கொள்ள தயாரா?",
  "final.sub": "உங்கள் இலவச கணக்கை உருவாக்கி இன்றே Gloows365-ஐ ஆராய்வதைத் தொடங்குங்கள்.",
  "final.ctaPrimary": "🚀 லாகின் / சைன் அப் — இலவசம்",
  "final.ctaSecondary": "ஏற்கனவே கணக்கு உள்ளதா?", "final.loginLink": "உள்நுழையவும்",

  "footer.tagline": "கற்றுக்கொள்ளுங்கள். போட்டியிடுங்கள். உருவாக்குங்கள். வெல்லுங்கள்.",
 "footer.navFeatures": "அம்சங்கள்", "footer.navAiGuru": "AI குரு",
