  "aiguru.eyebrow": "AI குரு",
  "aiguru.h2": "AI குருவை சந்திக்கவும்",
  "aiguru.sub": "உங்கள் AI-இயங்கும் கற்றல் துணை.",
  "aiguru.desc": "மாணவர்கள் கேள்விகள் கேட்கலாம், கருத்துக்களை ஆராயலாம் மற்றும் தேவைப்படும்போதெல்லாம் கற்றல் உதவியைப் பெறலாம் — புகைப்பட சந்தேக தீர்வு, தேர்வு தயாரிப்பு மற்றும் குரல் உரையாடல்கள் உட்பட.",
  "aiguru.cap1": "கேள்வி கேளுங்கள்",
  "aiguru.cap2": "புகைப்பட தீர்வு",
  "aiguru.cap3": "தேர்வு தயாரிப்பு",
  "aiguru.cap4": "குரல் ஆசிரியர்",
  "aiguru.cta": "AI குருவை ஆராயுங்கள் →",
  "aiguru.q": "வானம் ஏன் நீலமாகத் தெரிகிறது?",
  "aiguru.a": "படிப்படியாக புரிந்துகொள்வோம். சூரிய ஒளி வெண்மையாகத் தெரிகிறது, ஆனால் அது உண்மையில் பல வண்ணங்களால் ஆனது — நமது வளிமண்டலத்தின் வழியாக செல்லும்போது நீல ஒளி அதிகமாக சிதறுகிறது...",
  "seekho.eyebrow": "சீக்ஹோ",
