  "reels.eyebrow": "கல்வி ரீல்ஸ்",
  "reels.h2": "நொடிகளில் புதிதாக ஒன்றைக் கற்றுக்கொள்ளுங்கள்.",
  "reels.sub": "சிறு வீடியோக்கள். பயனுள்ள அறிவு. சிறந்த கற்றல்.",
  "reels.desc": "ரீல்ஸ் மாணவர்களுக்கு ஷார்ட்-ஃபார்ம் உள்ளடக்கத்தை மேலும் கல்வியியல் மற்றும் பயனுள்ளதாக்க வடிவமைக்கப்பட்டுள்ளது — வெறும் பொழுதுபோக்கு அல்ல, உண்மையான பாடங்களை மையமாகக் கொண்டது.",
