  "parent.p1t": "వయసుకు తగిన లెర్నింగ్", "parent.p1d": "కంటెంట్ మరియు ఫీచర్లు ప్రత్యేకంగా తరగతులు 6–12 కోసం నిర్మించబడ్డాయి.",
  "parent.p2t": "బాధ్యతాయుతమైన AI వినియోగం", "parent.p2d": "AI గురు నేర్చుకోవడానికి సహాయం చేయడానికి రూపొందించబడింది, దానిని భర్తీ చేయడానికి కాదు.",
  "parent.p3t": "కంటెంట్ మోడరేషన్", "parent.p3d": "స్కిల్ బ్యాటిల్ మరియు రీల్స్ సమర్పణలు మోడరేషన్‌ను దృష్టిలో ఉంచుకుని రూపొందించబడ్డాయి.",
