  "how.eyebrow": "ఇది ఎలా పని చేస్తుంది", "how.h2": "నాలుగు సాధారణ దశల్లో ప్రారంభించండి",
  "how.sub": "వెయిటింగ్ లిస్ట్ లేదు. ఆహ్వానం అవసరం లేదు. మీ ఖాతాను సృష్టించి ప్రారంభించండి.",
