  "faq.q1": "Gloows365 ఉచితమా?",
  "faq.a1": "అవును — మీరు Gloows365లో ఉచితంగా ఖాతాను సృష్టించి నేర్చుకోవడం ప్రారంభించవచ్చు.",
  "faq.q2": "ఏ తరగతులు మద్దతు ఇవ్వబడతాయి?",
  "faq.a2": "Gloows365 ప్రస్తుతం తరగతులు 6 నుండి 12 వరకు విద్యార్థులకు మద్దతు ఇస్తుంది.",
  "faq.q3": "ఏ బోర్డులు మద్దతు ఇవ్వబడతాయి?",
  "faq.a3": "CBSE, ICSE, రాష్ట్ర బోర్డులు మరియు ఇతర బోర్డులకు మద్దతు ఉంది.",
  "faq.q4": "Gloows365 భారతీయ భాషలకు మద్దతు ఇస్తుందా?",
  "faq.a4": "అవును — Gloows365 12 భారతీయ భాషలలో అందుబాటులో ఉంది.",
  "faq.q5": "Gloows365 ఆండ్రాయిడ్‌లో అందుబాటులో ఉందా?",
  "faq.a5": "Gloows365 నేడు వెబ్ అనుభవంగా అందుబాటులో ఉంది — సైన్ అప్ చేసి ఏ బ్రౌజర్ నుండైనా నేర్చుకోవడం ప్రారంభించండి.",
  "faq.q6": "Gloows365 తల్లిదండ్రుల కోసమా లేదా విద్యార్థుల కోసమా?",
  "faq.a6": "రెండూ. విద్యార్థులు నేర్చుకోవడానికి, సాధన చేయడానికి మరియు ఎదగడానికి Gloows365ని ఉపయోగిస్తారు, తల్లిదండ్రులు దీన్ని వ్యవస్థీకృత, విద్యా-కేంద్రీకృత అనుభవంగా విశ్వసించవచ్చు.",
  "faq.q7": "AI గురు అంటే ఏమిటి?",
  "faq.a7": "AI గురు అనేది Gloows365 యొక్క AI-ఆధారిత లెర్నింగ్ సహచరుడు, విద్యార్థులు ప్రశ్నలు అడగడానికి, భావనలను అన్వేషించడానికి మరియు లెర్నింగ్ సహాయం పొందడానికి రూపొందించబడింది.",
  "faq.q8": "విద్యా స్టార్ అంటే ఏమిటి?",
  "faq.a8": "విద్యా స్టార్ అనేది MCQ-ఆధారిత నాలెడ్జ్ ఛాలెంజ్, ఇది రివిజన్‌ను ఆకర్షణీయమైన కార్యకలాపంగా మారుస్తుంది.",
  "faq.q9": "విద్యా రీల్స్ అంటే ఏమిటి?",
  "faq.a9": "విద్యా రీల్స్ అనేవి ఉపయోగకరమైన జ్ఞానాన్ని సెకన్లలో నేర్చుకోవడం సులభతరం చేసేలా రూపొందించిన చిన్న వీడియోలు.",
