  "parent.eyebrow": "ಪೋಷಕರಿಗಾಗಿ", "parent.h2": "ವಿದ್ಯಾರ್ಥಿಗಳಿಗಾಗಿ ನಿರ್ಮಿಸಲಾಗಿದೆ. ಪೋಷಕರ ನಂಬಿಕೆ.",
  "parent.sub": "ವಿದ್ಯಾರ್ಥಿ ಸುರಕ್ಷತೆ ಮತ್ತು ಜವಾಬ್ದಾರಿಯುತ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು Gloows365 ರೂಪಿಸಲಾಗಿದೆ.",
