  "parent.p3t": "ವಿಷಯ ಮಾಡರೇಶನ್", "parent.p3d": "ಸ್ಕಿಲ್ ಬ್ಯಾಟಲ್ ಮತ್ತು ರೀಲ್ಸ್ ಸಲ್ಲಿಕೆಗಳನ್ನು ಮಾಡರೇಶನ್ ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ.",
