  "how.eyebrow": "ಇದು ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ", "how.h2": "ನಾಲ್ಕು ಸರಳ ಹಂತಗಳಲ್ಲಿ ಪ್ರಾರಂಭಿಸಿ",
  "how.sub": "ಕಾಯುವ ಪಟ್ಟಿ ಇಲ್ಲ. ಆಹ್ವಾನ ಬೇಕಿಲ್ಲ. ನಿಮ್ಮ ಖಾತೆಯನ್ನು ರಚಿಸಿ ಮತ್ತು ಪ್ರಾರಂಭಿಸಿ.",
