  "what.note": "ಜೊತೆಗೆ ಪ್ರತಿಭೆಯನ್ನು ಪ್ರದರ್ಶಿಸಲು <strong>ಸ್ಕಿಲ್ ಬ್ಯಾಟಲ್</strong> ಮತ್ತು ಕಲಿಕೆ ಮತ್ತು ಭಾಗವಹಿಸುವಿಕೆಗೆ ಬಹುಮಾನ ಗಳಿಸಲು <strong>VCoins</strong>.",
