  "parent.note": "ವಿದ್ಯಾರ್ಥಿ ಸುರಕ್ಷತೆ ಮತ್ತು ಜವಾಬ್ದಾರಿಯುತ ಭಾಗವಹಿಸುವಿಕೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು Gloows365 ರೂಪಿಸಲಾಗಿದೆ. ನಮ್ಮ",
