  "faq.eyebrow": "ಪ್ರಶ್ನೋತ್ತರ",
  "faq.h2": "ಪದೇ ಪದೇ ಕೇಳಲಾಗುವ ಪ್ರಶ್ನೆಗಳು",
  "faq.q1": "Gloows365 ಉಚಿತವೇ?",
  "faq.a1": "ಹೌದು — ನೀವು Gloows365 ನಲ್ಲಿ ಉಚಿತವಾಗಿ ಖಾತೆಯನ್ನು ರಚಿಸಿ ಕಲಿಕೆಯನ್ನು ಪ್ರಾರಂಭಿಸಬಹುದು.",
  "faq.q2": "ಯಾವ ತರಗತಿಗಳಿಗೆ ಬೆಂಬಲವಿದೆ?",
  "faq.a2": "Gloows365 ಪ್ರಸ್ತುತ ತರಗತಿ 6 ರಿಂದ 12 ರವರೆಗಿನ ವಿದ್ಯಾರ್ಥಿಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ.",
  "faq.q3": "ಯಾವ ಬೋರ್ಡ್‌ಗಳಿಗೆ ಬೆಂಬಲವಿದೆ?",
  "faq.a3": "CBSE, ICSE, ರಾಜ್ಯ ಬೋರ್ಡ್‌ಗಳು ಮತ್ತು ಇತರ ಬೋರ್ಡ್‌ಗಳಿಗೆ ಬೆಂಬಲವಿದೆ.",
  "faq.q4": "Gloows365 ಭಾರತೀಯ ಭಾಷೆಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆಯೇ?",
  "faq.a4": "ಹೌದು — Gloows365 12 ಭಾರತೀಯ ಭಾಷೆಗಳಲ್ಲಿ ಲಭ್ಯವಿದೆ.",
  "faq.q5": "Gloows365 ಆಂಡ್ರಾಯ್ಡ್‌ನಲ್ಲಿ ಲಭ್ಯವಿದೆಯೇ?",
  "faq.a5": "Gloows365 ಇಂದು ವೆಬ್ ಅನುಭವವಾಗಿ ಲಭ್ಯವಿದೆ — ಸೈನ್ ಅಪ್ ಮಾಡಿ ಯಾವುದೇ ಬ್ರೌಸರ್‌ನಿಂದ ಕಲಿಕೆಯನ್ನು ಪ್ರಾರಂಭಿಸಿ.",
  "faq.q6": "Gloows365 ಪೋಷಕರಿಗಾಗಿಯೇ ಅಥವಾ ವಿದ್ಯಾರ್ಥಿಗಳಿಗಾಗಿಯೇ?",
  "faq.a6": "ಎರಡಕ್ಕೂ. ವಿದ್ಯಾರ್ಥಿಗಳು ಕಲಿಯಲು, ಅಭ್ಯಾಸ ಮಾಡಲು ಮತ್ತು ಬೆಳೆಯಲು Gloows365 ಬಳಸುತ್ತಾರೆ, ಪೋಷಕರು ಇದನ್ನು ಸಂಘಟಿತ, ಶಿಕ್ಷಣ-ಕೇಂದ್ರಿತ ಅನುಭವವಾಗಿ ನಂಬಬಹುದು.",
  "faq.q7": "AI ಗುರು ಎಂದರೇನು?",
  "faq.a7": "AI ಗುರು ಎಂದರೆ Gloows365 ನ AI-ಚಾಲಿತ ಕಲಿಕಾ ಸಂಗಾತಿ, ವಿದ್ಯಾರ್ಥಿಗಳು ಪ್ರಶ್ನೆಗಳನ್ನು ಕೇಳಲು, ಪರಿಕಲ್ಪನೆಗಳನ್ನು ಅನ್ವೇಷಿಸಲು ಮತ್ತು ಕಲಿಕಾ ಸಹಾಯ ಪಡೆಯಲು ಸಹಾಯ ಮಾಡಲು ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ.",
  "faq.q8": "ವಿದ್ಯಾ ಸ್ಟಾರ್ ಎಂದರೇನು?",
