  "lang.eyebrow": "ഇന്ത്യക്കായി രൂപകൽപ്പന ചെയ്തത്", "lang.h2": "ഇന്ത്യ പല ഭാഷകളിൽ പഠിക്കുന്നു.",
  "lang.sub": "ഇന്ത്യയിലെ വൈവിധ്യമാർന്ന ഭാഷകളിലും വിദ്യാർത്ഥി സമൂഹങ്ങളിലും പഠനം ലഭ്യമാക്കാൻ Gloows365 രൂപകൽപ്പന ചെയ്തിരിക്കുന്നു.",

