  "parent.eyebrow": "രക്ഷിതാക്കൾക്കായി", "parent.h2": "വിദ്യാർത്ഥികൾക്കായി നിർമ്മിച്ചത്. രക്ഷിതാക്കളുടെ വിശ്വാസം.",
  "parent.sub": "വിദ്യാർത്ഥി സുരക്ഷയും ഉത്തരവാദിത്തമുള്ള പങ്കാളിത്തവും മനസ്സിൽ വെച്ചാണ് Gloows365 രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്.",
  "parent.p1t": "പ്രായത്തിന് അനുയോജ്യമായ പഠനം", "parent.p1d": "ഉള്ളടക്കവും ഫീച്ചറുകളും പ്രത്യേകമായി ക്ലാസ് 6–12 നായി നിർമ്മിച്ചത്.",
