  "parent.p3t": "ഉള്ളടക്ക മോഡറേഷൻ", "parent.p3d": "സ്കിൽ ബാറ്റിൽ, റീൽസ് സമർപ്പണങ്ങൾ മോഡറേഷൻ മനസ്സിൽ വെച്ചാണ് രൂപകൽപ്പന ചെയ്തിരിക്കുന്നത്.",
  "parent.p4t": "സ്വകാര്യത ആദ്യം", "parent.p4d": "വിദ്യാർത്ഥി ഡാറ്റ ഇന്ത്യയുടെ DPDP നിയമപ്രകാരം ഞങ്ങളുടെ സ്വകാര്യതാ നയമനുസരിച്ച് കൈകാര്യം ചെയ്യുന്നു.",
  "how.eyebrow": "ഇത് എങ്ങനെ പ്രവർത്തിക്കുന്നു", "how.h2": "നാല് ലളിതമായ ഘട്ടങ്ങളിൽ ആരംഭിക്കൂ",
