  "how.step1t": "നിങ്ങളുടെ സൗജന്യ അക്കൗണ്ട് ഉണ്ടാക്കൂ", "how.step1d": "നിങ്ങളുടെ ഫോൺ അല്ലെങ്കിൽ ഇമെയിൽ ഉപയോഗിച്ച് മിനിറ്റുകൾക്കുള്ളിൽ സൈൻ അപ്പ് ചെയ്യൂ.",
