  "aiguru.desc": "വിദ്യാർത്ഥികൾക്ക് ചോദ്യങ്ങൾ ചോദിക്കാം, ആശയങ്ങൾ പര്യവേക്ഷണം ചെയ്യാം, ആവശ്യമുള്ളപ്പോഴെല്ലാം പഠന സഹായം നേടാം — ഫോട്ടോ അടിസ്ഥാനമാക്കിയുള്ള സംശയ പരിഹാരം, പരീക്ഷാ തയ്യാറെടുപ്പ്, വോയ്സ് സംഭാഷണങ്ങൾ എന്നിവയുൾപ്പെടെ.",
  "aiguru.cap1": "ചോദ്യം ചോദിക്കൂ",
