  "aiguru.cap4": "വോയ്സ് ട്യൂട്ടർ",
  "aiguru.cta": "AI ഗുരു പര്യവേക്ഷണം ചെയ്യൂ →",
  "aiguru.q": "ആകാശം നീലയായി കാണുന്നത് എന്തുകൊണ്ട്?",
  "aiguru.a": "നമുക്ക് ഘട്ടം ഘട്ടമായി മനസ്സിലാക്കാം. സൂര്യപ്രകാശം വെളുത്തതായി കാണപ്പെടുന്നു, പക്ഷേ ഇത് യഥാർത്ഥത്തിൽ പല നിറങ്ങളാൽ നിർമ്മിതമാണ് — നമ്മുടെ അന്തരീക്ഷത്തിലൂടെ കടന്നുപോകുമ്പോൾ നീല വെളിച്ചം ഏറ്റവും കൂടുതൽ ചിതറുന്നു...",
  "seekho.eyebrow": "സീഖോ",
  "seekho.h2": "നിങ്ങളുടെ സ്വന്തം വേഗതയിൽ പഠിക്കൂ.",
