  "reels.desc": "വിദ്യാർത്ഥികൾക്കായി ഷോർട്ട്-ഫോം ഉള്ളടക്കത്തെ കൂടുതൽ വിദ്യാഭ്യാസപരവും ഉപകാരപ്രദവുമാക്കാൻ റീൽസ് രൂപകൽപ്പന ചെയ്തിരിക്കുന്നു — വെറും വിനോദമല്ല, യഥാർത്ഥ വിഷയങ്ങൾക്ക് ചുറ്റും നിർമ്മിച്ചത്.",
