  "problem.h2": "പഠനം ക്ലാസ്‌മുറിയുടെ വാതിൽക്കൽ നിൽക്കരുത്.",
  "problem.sub": "ഇന്നത്തെ വിദ്യാർത്ഥികൾക്ക് ഉള്ളടക്കത്തിലേക്ക് അനന്തമായ പ്രവേശനമുണ്ട്. യഥാർത്ഥ വെല്ലുവിളി ശരിയായ പഠന അനുഭവം കണ്ടെത്തുക എന്നതാണ് — ക്രമീകൃതവും ആകർഷകവും മനസ്സിലാക്കാൻ എളുപ്പവുമായത്.",
  "what.eyebrow": "Gloows365",
  "what.h2": "ഒരു പഠന പ്ലാറ്റ്ഫോം. വളരാൻ പല വഴികൾ.",
  "what.sub": "Gloows365 ക്രമീകൃത പഠനം, AI സഹായം, ദൈനംദിന പരിശീലനം, വിദ്യാഭ്യാസ ചെറു വീഡിയോകൾ എന്നിവ ഒരിടത്ത് കൊണ്ടുവരുന്നു.",
