  "what.practiceDesc": "ദൈനംദിന പഠന ശീലം കെട്ടിപ്പടുക്കുകയും MCQ കൾ ഉപയോഗിച്ച് നിങ്ങളുടെ അറിവിനെ വെല്ലുവിളിക്കുകയും ചെയ്യൂ.",
