  "faq.h2": "പതിവായി ചോദിക്കുന്ന ചോദ്യങ്ങൾ",
  "faq.q1": "Gloows365 സൗജന്യമാണോ?",
  "faq.a1": "അതെ — നിങ്ങൾക്ക് Gloows365-ൽ സൗജന്യമായി അക്കൗണ്ട് ഉണ്ടാക്കി പഠനം ആരംഭിക്കാം.",
  "faq.q2": "ഏതൊക്കെ ക്ലാസുകൾക്കാണ് പിന്തുണ?",
  "faq.a2": "Gloows365 നിലവിൽ ക്ലാസ് 6 മുതൽ 12 വരെയുള്ള വിദ്യാർത്ഥികളെ പിന്തുണയ്ക്കുന്നു.",
  "faq.q3": "ഏതൊക്കെ ബോർഡുകൾക്കാണ് പിന്തുണ?",
  "faq.a3": "CBSE, ICSE, സ്റ്റേറ്റ് ബോർഡുകൾ, മറ്റ് ബോർഡുകൾ എന്നിവയ്ക്ക് പിന്തുണയുണ്ട്.",
  "faq.q4": "Gloows365 ഇന്ത്യൻ ഭാഷകളെ പിന്തുണയ്ക്കുന്നുണ്ടോ?",
  "faq.a4": "അതെ — Gloows365 12 ഇന്ത്യൻ ഭാഷകളിൽ ലഭ്യമാണ്.",
  "faq.q5": "Gloows365 ആൻഡ്രോയിഡിൽ ലഭ്യമാണോ?",
  "faq.a5": "Gloows365 ഇന്ന് ഒരു വെബ് അനുഭവമായി ലഭ്യമാണ് — സൈൻ അപ്പ് ചെയ്ത് ഏത് ബ്രൗസറിൽ നിന്നും പഠനം ആരംഭിക്കൂ.",
  "faq.q6": "Gloows365 രക്ഷിതാക്കൾക്കോ വിദ്യാർത്ഥികൾക്കോ വേണ്ടിയാണോ?",
  "faq.a6": "രണ്ടിനും. വിദ്യാർത്ഥികൾ പഠിക്കാനും പരിശീലിക്കാനും വളരാനും Gloows365 ഉപയോഗിക്കുന്നു, രക്ഷിതാക്കൾക്ക് ഇത് ഒരു ക്രമീകൃതവും വിദ്യാഭ്യാസ-കേന്ദ്രീകൃതവുമായ അനുഭവമായി വിശ്വസിക്കാം.",
  "faq.q7": "AI ഗുരു എന്താണ്?",
  "faq.a7": "AI ഗുരു എന്നത് Gloows365-ന്റെ AI-അധിഷ്ഠിത പഠന കൂട്ടുകാരനാണ്, വിദ്യാർത്ഥികളെ ചോദ്യങ്ങൾ ചോദിക്കാനും ആശയങ്ങൾ പര്യവേക്ഷണം ചെയ്യാനും പഠന സഹായം നേടാനും സഹായിക്കാൻ രൂപകൽപ്പന ചെയ്തിരിക്കുന്നു.",
  "faq.q8": "വിദ്യാ സ്റ്റാർ എന്താണ്?",
  "faq.a8": "വിദ്യാ സ്റ്റാർ എന്നത് ഒരു MCQ അധിഷ്ഠിത വിജ്ഞാന വെല്ലുവിളിയാണ്, ഇത് പുനരവലോകനത്തെ ആകർഷകമായ ഒരു പ്രവർത്തനമാക്കി മാറ്റുന്നു.",
  "faq.q9": "വിദ്യാഭ്യാസ റീൽസ് എന്താണ്?",
  "faq.a9": "ഉപകാരപ്രദമായ അറിവ് സെക്കൻഡുകളിൽ പഠിക്കാൻ എളുപ്പമാക്കുന്ന ചെറു വീഡിയോകളാണ് വിദ്യാഭ്യാസ റീൽസ്.",
