  "faq.q6": "Gloows365 पालकांसाठी आहे की विद्यार्थ्यांसाठी?",
  "faq.a6": "दोघांसाठीही. विद्यार्थी शिकण्यासाठी, सराव करण्यासाठी आणि वाढण्यासाठी Gloows365 वापरतात, तर पालक याला एक व्यवस्थित, शिक्षण-केंद्रित अनुभव म्हणून विश्वास ठेवू शकतात.",
  "faq.q7": "AI गुरु म्हणजे काय?",
  "faq.a7": "AI गुरु हा Gloows365 चा AI-आधारित लर्निंग सोबती आहे, जो विद्यार्थ्यांना प्रश्न विचारण्यास, संकल्पना समजून घेण्यास आणि लर्निंग मदत मिळवण्यास मदत करण्यासाठी डिझाइन केलेला आहे.",
  "faq.q8": "विद्या स्टार म्हणजे काय?",
  "faq.a8": "विद्या स्टार हे एक MCQ-आधारित नॉलेज चॅलेंज आहे जे उजळणीला एक आकर्षक क्रियाकलाप बनवते.",
  "faq.q9": "शैक्षणिक रील्स म्हणजे काय?",
  "faq.a9": "शैक्षणिक रील्स हे छोटे व्हिडिओ आहेत जे उपयुक्त ज्ञान सेकंदात शिकणे सोपे करण्यासाठी डिझाइन केलेले आहेत.",
