  "parent.eyebrow": "વાલીઓ માટે", "parent.h2": "વિદ્યાર્થીઓ માટે બનાવેલ. વાલીઓનો વિશ્વાસ.",
  "parent.sub": "Gloows365 વિદ્યાર્થી સુરક્ષા અને જવાબદાર ભાગીદારીને ધ્યાનમાં રાખીને ડિઝાઇન કરાયેલ છે.",
  "parent.p1t": "ઉંમરને અનુરૂપ શિક્ષણ", "parent.p1d": "કન્ટેન્ટ અને ફીચર્સ ખાસ ધોરણ 6–12 માટે બનાવવામાં આવ્યા છે.",
