  "parent.p4t": "પ્રાઇવસી પ્રથમ", "parent.p4d": "વિદ્યાર્થી ડેટા ભારતના DPDP કાયદા હેઠળ અમારી પ્રાઇવસી પોલિસી મુજબ સંભાળવામાં આવે છે.",
  "how.eyebrow": "આ કેવી રીતે કામ કરે છે", "how.h2": "ચાર સરળ પગલાંમાં શરૂ કરો",
