  "lang.sub": "Gloows365 ਨੂੰ ਭਾਰਤ ਦੀਆਂ ਵਿਭਿੰਨ ਭਾਸ਼ਾਵਾਂ ਅਤੇ ਵਿਦਿਆਰਥੀ ਭਾਈਚਾਰਿਆਂ ਵਿੱਚ ਸਿੱਖਣ ਨੂੰ ਪਹੁੰਚਯੋਗ ਬਣਾਉਣ ਲਈ ਡਿਜ਼ਾਈਨ ਕੀਤਾ ਗਿਆ ਹੈ।",

