  "parent.eyebrow": "ਮਾਪਿਆਂ ਲਈ", "parent.h2": "ਵਿਦਿਆਰਥੀਆਂ ਲਈ ਬਣਾਇਆ ਗਿਆ। ਮਾਪਿਆਂ ਦਾ ਭਰੋਸਾ।",
  "parent.sub": "Gloows365 ਨੂੰ ਵਿਦਿਆਰਥੀ ਸੁਰੱਖਿਆ ਅਤੇ ਜ਼ਿੰਮੇਵਾਰ ਭਾਗੀਦਾਰੀ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖ ਕੇ ਡਿਜ਼ਾਈਨ ਕੀਤਾ ਗਿਆ ਹੈ।",
  "parent.p1t": "ਉਮਰ-ਅਨੁਕੂਲ ਸਿੱਖਿਆ", "parent.p1d": "ਸਮੱਗਰੀ ਅਤੇ ਫੀਚਰ ਖਾਸ ਤੌਰ 'ਤੇ ਜਮਾਤ 6–12 ਲਈ ਬਣਾਏ ਗਏ ਹਨ।",
  "parent.p2t": "ਜ਼ਿੰਮੇਵਾਰ AI ਵਰਤੋਂ", "parent.p2d": "AI ਗੁਰੂ ਸਿੱਖਣ ਵਿੱਚ ਮਦਦ ਕਰਨ ਲਈ ਬਣਾਇਆ ਗਿਆ ਹੈ, ਉਸਦੀ ਥਾਂ ਲੈਣ ਲਈ ਨਹੀਂ।",
  "parent.p3t": "ਸਮੱਗਰੀ ਮੌਡਰੇਸ਼ਨ", "parent.p3d": "ਸਕਿੱਲ ਬੈਟਲ ਅਤੇ ਰੀਲਾਂ ਦੀਆਂ ਸਬਮਿਸ਼ਨਾਂ ਨੂੰ ਮੌਡਰੇਸ਼ਨ ਨੂੰ ਧਿਆਨ ਵਿੱਚ ਰੱਖ ਕੇ ਡਿਜ਼ਾਈਨ ਕੀਤਾ ਗਿਆ ਹੈ।",
  "parent.p4t": "ਪ੍ਰਾਈਵੇਸੀ ਸਭ ਤੋਂ ਪਹਿਲਾਂ", "parent.p4d": "ਵਿਦਿਆਰਥੀ ਡਾਟਾ ਭਾਰਤ ਦੇ DPDP ਐਕਟ ਤਹਿਤ ਸਾਡੀ ਪ੍ਰਾਈਵੇਸੀ ਨੀਤੀ ਅਨੁਸਾਰ ਸੰਭਾਲਿਆ ਜਾਂਦਾ ਹੈ।",
  "how.eyebrow": "ਇਹ ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ", "how.h2": "ਚਾਰ ਆਸਾਨ ਕਦਮਾਂ ਵਿੱਚ ਸ਼ੁਰੂ ਕਰੋ",
  "how.sub": "ਕੋਈ ਵੇਟਿੰਗ ਲਿਸਟ ਨਹੀਂ। ਕਿਸੇ ਸੱਦੇ ਦੀ ਲੋੜ ਨਹੀਂ। ਬੱਸ ਆਪਣਾ ਖਾਤਾ ਬਣਾਓ ਅਤੇ ਸ਼ੁਰੂ ਕਰੋ।",
  "how.step1t": "ਆਪਣਾ ਮੁਫ਼ਤ ਖਾਤਾ ਬਣਾਓ", "how.step1d": "ਆਪਣੇ ਫੋਨ ਜਾਂ ਈਮੇਲ ਨਾਲ ਮਿੰਟਾਂ ਵਿੱਚ ਸਾਈਨ ਅੱਪ ਕਰੋ।",
  "how.step2t": "ਆਪਣੀ ਲਰਨਿੰਗ ਯਾਤਰਾ ਚੁਣੋ", "how.step2d": "ਆਪਣੀ ਜਮਾਤ, ਬੋਰਡ ਅਤੇ ਪਸੰਦੀਦਾ ਭਾਸ਼ਾ ਸੈੱਟ ਕਰੋ।",
  "how.step3t": "ਸਿੱਖੋ, ਅਭਿਆਸ ਕਰੋ ਅਤੇ ਮੁਕਾਬਲਾ ਕਰੋ", "how.step3d": "AI ਗੁਰੂ ਦੀ ਵਰਤੋਂ ਕਰੋ, ਕੁਇਜ਼ ਲਓ ਅਤੇ ਸਕਿੱਲ ਬੈਟਲ ਵਿੱਚ ਸ਼ਾਮਲ ਹੋਵੋ।",
  "how.cta": "ਮੁਫ਼ਤ ਸ਼ੁਰੂ ਕਰੋ →",

