  "faq.a2": "Gloows365 ਇਸ ਵੇਲੇ ਜਮਾਤ 6 ਤੋਂ 12 ਦੇ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਸਪੋਰਟ ਕਰਦਾ ਹੈ।",
  "faq.q3": "ਕਿਹੜੇ ਬੋਰਡ ਸਪੋਰਟਡ ਹਨ?",
  "faq.a3": "CBSE, ICSE, ਸਟੇਟ ਬੋਰਡ ਅਤੇ ਹੋਰ ਬੋਰਡ ਸਪੋਰਟਡ ਹਨ।",
  "faq.q4": "ਕੀ Gloows365 ਭਾਰਤੀ ਭਾਸ਼ਾਵਾਂ ਨੂੰ ਸਪੋਰਟ ਕਰਦਾ ਹੈ?",
  "faq.a4": "ਹਾਂ — Gloows365 12 ਭਾਰਤੀ ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਉਪਲਬਧ ਹੈ।",
  "faq.q5": "ਕੀ Gloows365 ਐਂਡਰਾਇਡ 'ਤੇ ਉਪਲਬਧ ਹੈ?",
  "faq.a5": "Gloows365 ਅੱਜ ਇੱਕ ਵੈੱਬ ਅਨੁਭਵ ਵਜੋਂ ਉਪਲਬਧ ਹੈ — ਸਾਈਨ ਅੱਪ ਕਰੋ ਅਤੇ ਕਿਸੇ ਵੀ ਬ੍ਰਾਊਜ਼ਰ ਤੋਂ ਸਿੱਖਣਾ ਸ਼ੁਰੂ ਕਰੋ।",
  "faq.q6": "ਕੀ Gloows365 ਮਾਪਿਆਂ ਲਈ ਹੈ ਜਾਂ ਵਿਦਿਆਰਥੀਆਂ ਲਈ?",
  "faq.a6": "ਦੋਵਾਂ ਲਈ। ਵਿਦਿਆਰਥੀ ਸਿੱਖਣ, ਅਭਿਆਸ ਕਰਨ ਅਤੇ ਅੱਗੇ ਵਧਣ ਲਈ Gloows365 ਵਰਤਦੇ ਹਨ, ਜਦਕਿ ਮਾਪੇ ਇਸ ਨੂੰ ਇੱਕ ਵਿਵਸਥਿਤ, ਸਿੱਖਿਆ-ਕੇਂਦਰਿਤ ਅਨੁਭਵ ਵਜੋਂ ਭਰੋਸਾ ਕਰ ਸਕਦੇ ਹਨ।",
  "faq.q7": "AI ਗੁਰੂ ਕੀ ਹੈ?",
  "faq.a7": "AI ਗੁਰੂ Gloows365 ਦਾ AI-ਸੰਚਾਲਿਤ ਲਰਨਿੰਗ ਸਾਥੀ ਹੈ, ਜੋ ਵਿਦਿਆਰਥੀਆਂ ਨੂੰ ਸਵਾਲ ਪੁੱਛਣ, ਸੰਕਲਪਾਂ ਨੂੰ ਸਮਝਣ ਅਤੇ ਲਰਨਿੰਗ ਮਦਦ ਲੈਣ ਵਿੱਚ ਮਦਦ ਲਈ ਡਿਜ਼ਾਈਨ ਕੀਤਾ ਗਿਆ ਹੈ।",
  "faq.q8": "ਵਿਦਿਆ ਸਟਾਰ ਕੀ ਹੈ?",
  "faq.a8": "ਵਿਦਿਆ ਸਟਾਰ ਇੱਕ MCQ-ਆਧਾਰਿਤ ਗਿਆਨ ਚੁਣੌਤੀ ਹੈ ਜੋ ਦੁਹਰਾਈ ਨੂੰ ਇੱਕ ਦਿਲਚਸਪ ਗਤੀਵਿਧੀ ਵਿੱਚ ਬਦਲ ਦਿੰਦੀ ਹੈ।",
  "faq.q9": "ਵਿਦਿਅਕ ਰੀਲਾਂ ਕੀ ਹਨ?",
  "faq.a9": "ਵਿਦਿਅਕ ਰੀਲਾਂ ਛੋਟੀਆਂ ਵੀਡੀਓਜ਼ ਹਨ ਜੋ ਲਾਭਦਾਇਕ ਗਿਆਨ ਨੂੰ ਸਕਿੰਟਾਂ ਵਿੱਚ ਸਿੱਖਣਾ ਆਸਾਨ ਬਣਾਉਣ ਲਈ ਡਿਜ਼ਾਈਨ ਕੀਤੀਆਂ ਗਈਆਂ ਹਨ।",
