  "parent.p3t": "ବିଷୟବସ୍ତୁ ମଡରେସନ୍", "parent.p3d": "ସ୍କିଲ୍ ବ୍ୟାଟଲ୍ ଏବଂ ରିଲ୍ସ ଦାଖଲଗୁଡିକ ମଡରେସନ୍ ମନରେ ରଖି ତିଆରି।",
