  "how.step1t": "ଆପଣଙ୍କ ମାଗଣା ଖାତା ତିଆରି କରନ୍ତୁ", "how.step1d": "ଆପଣଙ୍କ ଫୋନ କିମ୍ବା ଇମେଲ୍ ସହିତ ମିନିଟରେ ସାଇନ୍ ଅପ୍ କରନ୍ତୁ।",
  "how.step2t": "ଆପଣଙ୍କ ଲର୍ନିଂ ଯାତ୍ରା ବାଛନ୍ତୁ", "how.step2d": "ଆପଣଙ୍କ ଶ୍ରେଣୀ, ବୋର୍ଡ ଏବଂ ପସନ୍ଦିତ ଭାଷା ସେଟ୍ କରନ୍ତୁ।",
  "how.step3t": "ଶିଖନ୍ତୁ, ଅଭ୍ୟାସ କରନ୍ତୁ ଏବଂ ପ୍ରତିଯୋଗିତା କରନ୍ତୁ", "how.step3d": "AI ଗୁରୁ ବ୍ୟବହାର କରନ୍ତୁ, କୁଇଜ୍ ନିଅନ୍ତୁ ଏବଂ ସ୍କିଲ୍ ବ୍ୟାଟଲରେ ଯୋଗ ଦିଅନ୍ତୁ।",
