  "faq.a1": "ହଁ — ଆପଣ Gloows365 ରେ ମାଗଣାରେ ଏକାଉଣ୍ଟ ତିଆରି କରି ଶିଖିବା ଆରମ୍ଭ କରିପାରିବେ।",
  "faq.q2": "କେଉଁ ଶ୍ରେଣୀଗୁଡିକ ସପୋର୍ଟେଡ୍?",
  "faq.a2": "Gloows365 ବର୍ତ୍ତମାନ ଶ୍ରେଣୀ 6 ରୁ 12 ପର୍ଯ୍ୟନ୍ତ ଛାତ୍ରଛାତ୍ରୀଙ୍କୁ ସପୋର୍ଟ କରେ।",
  "faq.q3": "କେଉଁ ବୋର୍ଡଗୁଡିକ ସପୋର୍ଟେଡ୍?",
  "faq.a3": "CBSE, ICSE, ଷ୍ଟେଟ୍ ବୋର୍ଡ ଏବଂ ଅନ୍ୟାନ୍ୟ ବୋର୍ଡ ସପୋର୍ଟେଡ୍।",
  "faq.q4": "Gloows365 ଭାରତୀୟ ଭାଷାକୁ ସପୋର୍ଟ କରେ କି?",
  "faq.a4": "ହଁ — Gloows365 12 ଭାରତୀୟ ଭାଷାରେ ଉପଲବ୍ଧ।",
  "faq.q5": "Gloows365 ଆଣ୍ଡ୍ରଏଡରେ ଉପଲବ୍ଧ କି?",
  "faq.a5": "Gloows365 ଆଜି ଏକ ୱେବ୍ ଅଭିଜ୍ଞତା ଭାବରେ ଉପଲବ୍ଧ — ସାଇନ୍ ଅପ୍ କରନ୍ତୁ ଏବଂ ଯେକୌଣସି ବ୍ରାଉଜରରୁ ଶିଖିବା ଆରମ୍ଭ କରନ୍ତୁ।",
  "faq.q6": "Gloows365 ପିତାମାତାଙ୍କ ପାଇଁ ନା ଛାତ୍ରଛାତ୍ରୀଙ୍କ ପାଇଁ?",
  "faq.a6": "ଉଭୟଙ୍କ ପାଇଁ। ଛାତ୍ରଛାତ୍ରୀମାନେ ଶିଖିବା, ଅଭ୍ୟାସ କରିବା ଏବଂ ବଢିବା ପାଇଁ Gloows365 ବ୍ୟବହାର କରନ୍ତି, ଅନ୍ୟପଟେ ପିତାମାତା ଏହାକୁ ଏକ ସୁସଙ୍ଗଠିତ, ଶିକ୍ଷା-କେନ୍ଦ୍ରିତ ଅଭିଜ୍ଞତା ଭାବରେ ବିଶ୍ୱାସ କରିପାରନ୍ତି।",
  "faq.q7": "AI ଗୁରୁ କଣ?",
  "faq.a7": "AI ଗୁରୁ ହେଉଛି Gloows365 ର AI-ଚାଳିତ ଲର୍ନିଂ ସାଥୀ, ଯାହା ଛାତ୍ରଛାତ୍ରୀଙ୍କୁ ପ୍ରଶ୍ନ ପଚାରିବା, ଧାରଣା ବୁଝିବା ଏବଂ ଲର୍ନିଂ ସାହାଯ୍ୟ ପାଇବାରେ ସାହାଯ୍ୟ କରିବା ପାଇଁ ଡିଜାଇନ୍ କରାଯାଇଛି।",
  "faq.q8": "ବିଦ୍ୟା ଷ୍ଟାର୍ କଣ?",
  "faq.a8": "ବିଦ୍ୟା ଷ୍ଟାର୍ ହେଉଛି ଏକ MCQ-ଆଧାରିତ ଜ୍ଞାନ ଚ୍ୟାଲେଞ୍ଜ ଯାହା ପୁନରାବୃତ୍ତିକୁ ଏକ ଆକର୍ଷଣୀୟ କାର୍ଯ୍ୟକଳାପରେ ପରିଣତ କରେ।",
  "faq.q9": "ଶିକ୍ଷାମୂଳକ ରିଲ୍ସ କଣ?",
  "faq.a9": "ଶିକ୍ଷାମୂଳକ ରିଲ୍ସ ହେଉଛି ଛୋଟ ଭିଡିଓ ଯାହା ଉପଯୋଗୀ ଜ୍ଞାନକୁ ସେକେଣ୍ଡରେ ଶିଖିବା ସହଜ କରିବା ପାଇଁ ଡିଜାଇନ୍ କରାଯାଇଛି।",
