  "faq.h2": "সঘনাই সোধা প্ৰশ্ন",
  "faq.q1": "Gloows365 বিনামূলীয়া নে?",
  "faq.a1": "হয় — আপুনি Gloows365 ত বিনামূলীয়াকৈ একাউণ্ট সৃষ্টি কৰি শিকা আৰম্ভ কৰিব পাৰে।",
