  "faq.a2": "Gloows365এ বৰ্তমান শ্ৰেণী 6 ৰ পৰা 12 লৈকে শিক্ষাৰ্থীসকলক সমৰ্থন কৰে।",
  "faq.q3": "কি কি ব’ৰ্ড সমৰ্থিত?",
