  "faq.q6": "Gloows365 অভিভাৱকৰ বাবে নে শিক্ষাৰ্থীৰ বাবে?",
  "faq.a6": "দুয়োৰে বাবে। শিক্ষাৰ্থীসকলে শিকা, অনুশীলন কৰা আৰু আগবঢ়াৰ বাবে Gloows365 ব্যৱহাৰ কৰে, আনহাতে অভিভাৱকসকলে ইয়াক এক সুসংগঠিত, শিক্ষা-কেন্দ্ৰিক অভিজ্ঞতা হিচাপে বিশ্বাস কৰিব পাৰে।",
  "faq.q7": "AI গুৰু কি?",
  "faq.a7": "AI গুৰু হৈছে Gloows365 ৰ AI-চালিত শিক্ষণ সঙ্গী, যিয়ে শিক্ষাৰ্থীসকলক প্ৰশ্ন সোধিবলৈ, ধাৰণাসমূহ বুজিবলৈ আৰু শিক্ষণ সহায় লাভ কৰিবলৈ সহায় কৰিবলৈ ডিজাইন কৰা হৈছে।",
  "faq.q8": "বিদ্যা ষ্টাৰ কি?",
  "faq.a8": "বিদ্যা ষ্টাৰ হৈছে এটা MCQ-ভিত্তিক জ্ঞান প্ৰত্যাহ্বান যিয়ে পুনৰাবৃত্তিক এক আকৰ্ষণীয় কাৰ্যকলাপলৈ পৰিণত কৰে।",
  "faq.q9": "শৈক্ষিক ৰীল কি?",
  "faq.a9": "শৈক্ষিক ৰীল হৈছে চুটি ভিডিঅ' যিয়ে উপযোগী জ্ঞানক ছেকেণ্ডত শিকা সহজ কৰিবলৈ ডিজাইন কৰা হৈছে।",
